def comps(g,bg):
    H=len(g);W=len(g[0]);seen=set();out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)];seen.add((i,j));cells=[]
                while st:
                    y,x=st.pop();cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]!=bg and (ny,nx) not in seen:
                                seen.add((ny,nx));st.append((ny,nx))
                out.append(cells)
    return out
